<?php session_start(); include "db.php"; $msg="";
if($_SERVER["REQUEST_METHOD"]==="POST"){ $name=trim($_POST["name"]);$email=trim($_POST["email"]);$phone=trim($_POST["phone"]);$department=trim($_POST["department"]);$password=$_POST["password"];
if($name&&filter_var($email,FILTER_VALIDATE_EMAIL)&&$phone&&$department&&strlen($password)>=6){$hash=password_hash($password,PASSWORD_DEFAULT);$s=$conn->prepare("INSERT INTO employees(name,email,phone,department,password) VALUES(?,?,?,?,?)");$s->bind_param("sssss",$name,$email,$phone,$department,$hash);if($s->execute()){header("Location: login.php?registered=1");exit;}$msg="Email already exists.";}else $msg="Enter valid details. Password must be at least 6 characters."; } ?>
<!doctype html><html><head><title>Register</title><link rel="stylesheet" href="style.css"></head><body><div class="form"><form method="post"><h2>Employee Registration</h2><?php if($msg)echo"<p class=error>".htmlspecialchars($msg)."</p>";?><input name="name" placeholder="Full Name" required><input type="email" name="email" placeholder="Email" required><input name="phone" placeholder="Phone" required><input name="department" placeholder="Department" required><input type="password" name="password" placeholder="Password" required><button class="btn">Register</button><p><a href="login.php">Login</a> | <a href="index.php">Home</a></p></form></div></body></html>